export const INSTAGRAM_WORKSPACE_APP_CSS = ":root {\n  color-scheme: light dark;\n  --ig-bg: var(--color-background-primary, light-dark(#fff, #212121));\n  --ig-surface: var(--color-background-secondary, light-dark(#f5f6f4, #2c2c2c));\n  --ig-text: var(--color-text-primary, light-dark(#202820, #eee));\n  --ig-muted: var(--color-text-secondary, light-dark(#5d685d, #b7bdb7));\n  --ig-line: var(--color-border-primary, light-dark(#dfe5df, #484d48));\n}\n:root[data-theme=\"light\"] {\n  color-scheme: light;\n}\n:root[data-theme=\"dark\"] {\n  color-scheme: dark;\n}\n* {\n  box-sizing: border-box;\n}\nbody {\n  margin: 0;\n  color: var(--ig-text);\n  background: var(--ig-bg);\n  font: 14px/1.55 var(--font-sans-host, system-ui, sans-serif);\n}\nbutton,\ninput,\nselect,\ntextarea {\n  font: inherit;\n  color: inherit;\n}\nbutton {\n  cursor: pointer;\n  border: 1px solid var(--ig-line);\n  background: var(--ig-surface);\n  padding: 7px 11px;\n  border-radius: 7px;\n}\nbutton:hover:not(:disabled) {\n  filter: brightness(0.94);\n}\nbutton:disabled {\n  opacity: 0.5;\n  cursor: default;\n}\nbutton[aria-pressed=\"true\"] {\n  background: var(--ig-text);\n  color: var(--ig-bg);\n}\nbutton:focus-visible,\ninput:focus-visible,\nselect:focus-visible,\ntextarea:focus-visible {\n  outline: 2px solid var(--ig-text);\n  outline-offset: 2px;\n}\n.instagram-app {\n  max-width: 1100px;\n  margin: 0 auto;\n  padding: 24px;\n}\n.instagram-app h1 {\n  font-size: 27px;\n  line-height: 1.2;\n  margin: 4px 0 12px;\n}\n.instagram-app h2 {\n  font-size: 18px;\n  margin: 0 0 12px;\n}\n.eyebrow {\n  color: var(--ig-muted);\n  font-size: 11px;\n  text-transform: uppercase;\n  letter-spacing: 1.3px;\n}\n.instagram-panel {\n  border: 1px solid var(--ig-line);\n  padding: 18px;\n  border-radius: 12px;\n  margin: 18px 0;\n}\n.instagram-panel > label {\n  display: block;\n  margin: 12px 0 5px;\n  font-weight: 600;\n}\n.instagram-panel > select,\n.instagram-panel > textarea {\n  width: 100%;\n  margin-bottom: 12px;\n}\n.instagram-app input:not([type=\"checkbox\"]),\n.instagram-app select,\n.instagram-app textarea {\n  border: 1px solid var(--ig-line);\n  border-radius: 7px;\n  padding: 8px;\n  background: var(--ig-bg);\n}\n.instagram-muted,\nsmall,\nfooter {\n  color: var(--ig-muted);\n}\nsmall {\n  display: block;\n  font-size: 11px;\n  margin-top: 4px;\n}\n.instagram-filters,\n.instagram-actions {\n  display: flex;\n  gap: 8px;\n  flex-wrap: wrap;\n  align-items: center;\n  margin: 12px 0;\n}\n.instagram-table {\n  overflow: auto;\n  margin: 16px 0;\n}\n.instagram-table table {\n  width: 100%;\n  border-collapse: collapse;\n  min-width: 600px;\n  text-align: left;\n}\n.instagram-table th,\n.instagram-table td {\n  border-bottom: 1px solid var(--ig-line);\n  padding: 12px 8px;\n  vertical-align: top;\n  overflow-wrap: anywhere;\n}\n.instagram-table th {\n  font-size: 12px;\n  color: var(--ig-muted);\n}\n.profile-link {\n  border: 0;\n  padding: 0;\n  background: transparent;\n  text-decoration: underline;\n  text-underline-offset: 3px;\n}\n.instagram-error {\n  padding: 12px;\n  border: 1px solid var(--ig-line);\n  background: var(--ig-surface);\n  border-radius: 8px;\n}\n.quote-fields {\n  display: grid;\n  grid-template-columns: 1fr 2fr 1fr;\n  gap: 12px;\n  margin: 16px 0;\n}\n.quote-fields label {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\ndetails {\n  margin: 18px 0;\n}\nsummary {\n  cursor: pointer;\n  font-weight: 600;\n}\n.profile-biography {\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n}\ndl {\n  display: grid;\n  grid-template-columns: 140px 1fr;\n  gap: 6px;\n}\ndd {\n  margin: 0;\n}\n.saved-images {\n  display: flex;\n  gap: 12px;\n  flex-wrap: wrap;\n  margin: 16px 0;\n}\n.saved-images img {\n  width: 180px;\n  height: 180px;\n  object-fit: contain;\n  border-radius: 10px;\n  background: var(--ig-surface);\n}\n.criterion-result {\n  border-top: 1px solid var(--ig-line);\n  padding-top: 12px;\n  margin-top: 12px;\n}\n.criterion-result p {\n  overflow-wrap: anywhere;\n}\nfooter {\n  font-size: 12px;\n  margin: 20px 0;\n}\nli {\n  margin: 10px 0;\n}\n@media (max-width: 650px) {\n  .instagram-app {\n    padding: 14px;\n  }\n  .quote-fields {\n    grid-template-columns: 1fr;\n  }\n  .instagram-panel {\n    padding: 14px;\n  }\n  .instagram-table table {\n    min-width: 540px;\n  }\n  .saved-images img {\n    width: 140px;\n    height: 140px;\n  }\n}\n";
